func atomic_ptr8[T uint32 | uint64](mem []byte, addr T) (ptr *uint32, shift uint32) {
	ptr = (*uint32)(unsafe.Pointer(&mem[addr&^3]))
	shift = uint32(addr) & 3 * 8
	return
}

